def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    border_counts = Counter()
    for c in range(w):
        if grid[0][c] != bg:
            border_counts[grid[0][c]] += 1
        if grid[h - 1][c] != bg:
            border_counts[grid[h - 1][c]] += 1
    for r in range(1, h - 1):
        if grid[r][0] != bg:
            border_counts[grid[r][0]] += 1
        if grid[r][w - 1] != bg:
            border_counts[grid[r][w - 1]] += 1

    bar = border_counts.most_common(1)[0][0]
    dots = [(r, c) for r in range(h) for c in range(w)
            if grid[r][c] not in (bg, bar)]
    if not dots:
        return [row[:] for row in grid]
    dot_color = grid[dots[0][0]][dots[0][1]]
    out = [row[:] for row in grid]

    def runs(vals):
        result = []
        i = 0
        while i < len(vals):
            if vals[i] != bar:
                i += 1
                continue
            j = i
            while j + 1 < len(vals) and vals[j + 1] == bar:
                j += 1
            result.append((i, j))
            i = j + 1
        return result

    horizontal_edges = []
    if all(v == bar for v in grid[0]):
        pass
    horizontal_edges += [(0, a, b) for a, b in runs(grid[0])]
    horizontal_edges += [(h - 1, a, b) for a, b in runs(grid[h - 1])]

    vertical_edges = []
    vertical_edges += [(0, a, b) for a, b in runs([grid[r][0] for r in range(h)])]
    vertical_edges += [(w - 1, a, b) for a, b in runs([grid[r][w - 1] for r in range(h)])]

    def offsets_for(segments, axis):
        offsets = set()
        for r, c in dots:
            x = c if axis == "col" else r
            candidates = [(a, b) for _, a, b in segments if a <= x <= b]
            if candidates:
                # The dot's position within its border segment is the pattern
                # copied to the other segments.
                a, b = min(candidates, key=lambda ab: ab[1] - ab[0])
                offsets.add(x - a)
        return offsets

    def draw(segments, offsets, axis):
        for fixed, a, b in segments:
            for off in offsets:
                if off > b - a:
                    continue
                pos = a + off
                if axis == "col":
                    c = pos
                    r = 1 if fixed == 0 else h - 2
                    dr = 1 if fixed == 0 else -1
                    while 0 <= r < h:
                        if grid[r][c] == bar:
                            break
                        if grid[r][c] not in (bg, dot_color):
                            out[r][c] = 4
                            break
                        if grid[r][c] == dot_color:
                            out[r][c] = 4
                            break
                        out[r][c] = dot_color
                        r += dr
                else:
                    r = pos
                    c = 1 if fixed == 0 else w - 2
                    dc = 1 if fixed == 0 else -1
                    while 0 <= c < w:
                        if grid[r][c] == bar:
                            break
                        if grid[r][c] not in (bg, dot_color):
                            out[r][c] = 4
                            break
                        if grid[r][c] == dot_color:
                            out[r][c] = 4
                            break
                        out[r][c] = dot_color
                        c += dc

    draw(horizontal_edges, offsets_for(horizontal_edges, "col"), "col")
    draw(vertical_edges, offsets_for(vertical_edges, "row"), "row")
    return out
